// ================== CẤU HÌNH ==================
const CONFIG = {
  ATTACHMENT_SECRET: 'doi-chuoi-bi-mat-anh',            // giống hệt ATTACHMENT_SECRET trong Sync Watcher và Reply Assistant
  JIRA_BASE_URL: 'https://your-company.atlassian.net',
};
// ==============================================
// ---- HMAC-SHA256 thuần JS (Code node của n8n mặc định không cho require('crypto')) ----
function sha256(bytes) {
  const frac = (x) => ((x - Math.floor(x)) * 4294967296) >>> 0;
  const primes = []; for (let n = 2; primes.length < 64; n++) if (primes.every(p => n % p)) primes.push(n);
  const K = primes.map(p => frac(Math.cbrt(p)));
  const H = primes.slice(0, 8).map(p => frac(Math.sqrt(p)));
  const len = bytes.length, total = ((len + 9 + 63) >> 6) << 6;
  const buf = new Uint8Array(total); buf.set(bytes); buf[len] = 0x80;
  const dv = new DataView(buf.buffer);
  dv.setUint32(total - 4, (len * 8) >>> 0); dv.setUint32(total - 8, Math.floor(len / 536870912));
  const W = new Uint32Array(64), r = (x, n) => (x >>> n) | (x << (32 - n));
  for (let o = 0; o < total; o += 64) {
    for (let i = 0; i < 16; i++) W[i] = dv.getUint32(o + i * 4);
    for (let i = 16; i < 64; i++) {
      const s0 = r(W[i - 15], 7) ^ r(W[i - 15], 18) ^ (W[i - 15] >>> 3);
      const s1 = r(W[i - 2], 17) ^ r(W[i - 2], 19) ^ (W[i - 2] >>> 10);
      W[i] = (W[i - 16] + s0 + W[i - 7] + s1) | 0;
    }
    let [a, b, c, d, e, f, g, h] = H;
    for (let i = 0; i < 64; i++) {
      const t1 = (h + (r(e, 6) ^ r(e, 11) ^ r(e, 25)) + ((e & f) ^ (~e & g)) + K[i] + W[i]) | 0;
      const t2 = ((r(a, 2) ^ r(a, 13) ^ r(a, 22)) + ((a & b) ^ (a & c) ^ (b & c))) | 0;
      h = g; g = f; f = e; e = (d + t1) | 0; d = c; c = b; b = a; a = (t1 + t2) | 0;
    }
    [a, b, c, d, e, f, g, h].forEach((v, i) => { H[i] = (H[i] + v) >>> 0; });
  }
  const out = new Uint8Array(32); H.forEach((v, i) => new DataView(out.buffer).setUint32(i * 4, v)); return out;
}
const utf8 = (s) => Uint8Array.from(unescape(encodeURIComponent(String(s))), ch => ch.charCodeAt(0));
function hmacHex(key, msg) {
  let k = utf8(key); if (k.length > 64) k = sha256(k);
  const kp = new Uint8Array(64); kp.set(k);
  const inner = new Uint8Array(64 + utf8(msg).length); inner.set(kp.map(x => x ^ 0x36)); inner.set(utf8(msg), 64);
  const ih = sha256(inner);
  const outer = new Uint8Array(96); outer.set(kp.map(x => x ^ 0x5c)); outer.set(ih, 64);
  return [...sha256(outer)].map(x => x.toString(16).padStart(2, '0')).join('');
}

const q = $input.first().json.query || {};
const id = String(q.id || '');
if (!/^\d{1,12}$/.test(id)) throw new Error('Thiếu hoặc sai id');
if (!q.sig || q.sig !== hmacHex(CONFIG.ATTACHMENT_SECRET, id)) throw new Error('Chữ ký không hợp lệ');
const thumb = q.thumb === '1';
return [{ json: { url: `${CONFIG.JIRA_BASE_URL}/rest/api/3/attachment/${thumb ? 'thumbnail' : 'content'}/${id}${thumb ? '?redirect=true' : ''}` } }];
